from review import card,save,DATE
def b(t,s,r=None):
 d=dict(title=t,text=s)
 if r:d['citation']=r
 return d
def sm(s,r):return dict(sentences=s,basis='saved_sources',source_basis='source-text',written_on=DATE,source_refs=r)
def imp(c,s):return dict(score=c['importance']['score'],method='editorial',reason=s+' Existing numerical score retained.',assessed_on=DATE)
def unfinished(issue):return dict(reviewed_on=DATE,status='needs_specification',remaining_issue=issue,notes=['Recovered the source question and model; remaining conventions are explicit.'])

i='TCS-2342';_,c=card(i);refs=c['references'];refs[0]['locator']='ICALP 2023, article 12: introduction/Open Problem 2, Remark 4 and Corollaries 27–28 read. The source considers polynomial-degree families in the number of variables; the open paragraph does not fix a field, explicitness convention or exponent.'
refs.append(dict(id='depth2026',title='Lower Bounds for Depth-5 Algebraic Circuits with Bounded Fan-in of Top Product Gates',authors='Jules Armand, Amik Raj Behera, Sébastien Tavenas',year=2026,url='https://eccc.weizmann.ac.il/report/2026/104/',locator='24 June 2026 preprint: abstract and introduction read. Exponential depth-five bounds require small finite fields and bounded top-product fan-in; the general constant-depth problem remains distinct.'))
issue='The source asks for explicit polynomial families but does not fix the admissible explicitness class, the base field or the quantitative exponent of the requested exponential bound. These choices affect the target, especially in view of finite-field results. A fully quantified conjecture must specify them; no particular polynomial family or characteristic-zero restriction is silently substituted here.'
save(i,dict(title='Exponential lower bounds for constant-depth arithmetic formulas',formal='Can one exhibit explicit families of polynomials in n variables, of degree at most polynomial in n, that require exponentially large arithmetic formulas even when the formula depth is an arbitrary fixed constant? The source asks for a strengthening of known superpolynomial bounds. Its field, explicitness and exponential-rate conventions remain to be specified as described below.',definitions='An arithmetic formula over a field F is a finite rooted expression tree. Leaves are variables x₁,…,xₙ or constants from F, and internal gates add or multiply their children. Gates may have arbitrarily many inputs, and a computed subexpression is not shared by several parents. The output must equal the target as a formal polynomial, not merely as a function on Fⁿ. Size counts the tree’s gates and leaves; depth is the maximum number of operation gates on a root-to-leaf path. The depth bound is fixed independently of n, while the target polynomial degree is at most n^O(1). General formulas may use cancellation and nonhomogeneous intermediate polynomials. A homogeneous formula requires every gate’s polynomial to have all monomials of the same total degree. For context, a lower bound n^{Ω((log n)^c)} with fixed 0<c<1 is superpolynomial but far below 2^{n^α} for any fixed α>0. The open paragraph says “exponential” without choosing a bound of that form or fixing how its exponent may depend on depth. Mere existence of hard polynomials by counting does not fulfill its explicit-family intent.',question_type='yes_no',answer_criterion='A complete version must specify a field, a verifiable notion of explicit polynomial family and a numerical lower bound in n and the fixed depth. It must cover every formula in that model computing the chosen family. A bound that only applies to homogeneous, set-multilinear or specially bounded-fan-in formulas should be identified as a restricted-model result.',context_blocks=[b('Bounded depth still permits large computation','Unbounded fan-in lets one layer combine arbitrarily many terms. The question concerns how much expression size is necessary when only constantly many layers are available.'),b('The qualitative breakthrough is already known','The source discusses superpolynomial lower bounds for general constant-depth arithmetic formulas. The remaining target is a substantially larger quantitative lower bound, not the first separation from polynomial size.', 'primary'),b('Restrictions change which bounds are available','Exponential lower bounds are known for some homogeneous and set-multilinear models. Those restrictions rule out computations allowed by the general formula model and cannot be omitted from a progress claim.', 'primary'),b('A 2026 result still restricts depth-five circuits','Armand, Behera and Tavenas prove exponential bounds over small finite fields with a bound on the fan-in of top product gates. This advances a restricted case; it does not supply an exponential bound for unrestricted formulas at every fixed depth.', 'depth2026'),b('The remaining specification matters',issue)],why='Would quantify how severely constant depth limits algebraic computation, beyond the known superpolynomial separation; sufficiently strong bounds at particular shallow depths also connect to broader arithmetic lower-bound questions.',references=refs,progress=[dict(date='2023',text='The source asks to strengthen the existing superpolynomial constant-depth lower bounds to exponential ones.',citation='primary'),dict(date='2026-06-24',text='New exponential depth-five lower bounds cover small finite fields with bounded top-product fan-in.',citation='depth2026')],status='source_open',status_note='Original question and model read; checked the June 2026 restricted-depth-five preprint and subsequent-result searches through 12 September 2026. No full general resolution was located. The question remains incomplete at the convention level.',model_self_contained=False,requires_context=True,statement_review=unfinished(issue),importance=imp(c,'A central quantitative strengthening in arithmetic circuit lower bounds.'),review_note='Defined formulas, unbounded fan-in, polynomial degree and formal equality. Replaced generic context and separated restricted models without inventing the missing field or exponent.',working_summary=sm(['The question asks how large a constant-depth arithmetic expression must be to compute an explicit polynomial.','Addition and multiplication gates can have arbitrarily many inputs, and cancellation is allowed.','Superpolynomial lower bounds are known; the desired strengthening is exponential.','Recent exponential results impose extra restrictions on the field and the circuit.','The source still needs a precise field, explicitness convention and exponential rate before this becomes one fully quantified conjecture.'],['primary','depth2026'])),notes=['Recovered polynomial-degree families and the arbitrary-fan-in formula model.','Distinguished general formulas from homogeneous and set-multilinear restrictions.','Checked June 2026 progress and retained the genuinely missing conventions.'],checked_sources=[r['url'] for r in refs],state='improved_unfinished')

i='TCS-2367';_,c=card(i);refs=c['references'];refs[0]['locator']='APPROX 2023, article 21: definition of GMP in Section 1, Theorems 1–2 and final conjecture in Section 5 read. The displaced radical belongs to log n; n counts jobs.'
refs.append(dict(id='gmp_upper',title='Generalized Unrelated Machine Scheduling Problem',authors='Shichuan Deng, Jian Li, Yuval Rabani',year=2023,url='https://doi.org/10.1137/1.9781611977554.ch110',pdf_url='https://arxiv.org/pdf/2202.06292',locator='SODA 2023; full preprint introduction, Theorem 2, Section 2 and NormLin definition/Theorem 9 read. O(log n) approximation for general inner and outer norms; constant approximation for top-k inner norms with maximum outer objective.'))
issue='The objective and approximation ratio are recovered, but the source does not specify how arbitrary symmetric monotone norms are encoded or accessed, nor the bit/real-arithmetic cost model and randomized success convention for the conjectured algorithm. These must be fixed for a fully self-contained polynomial-time assertion; a succinct norm representation or a free norm oracle is not silently imposed.'
save(i,dict(title='A square-root-logarithmic approximation for generalized makespan',area='Approximation algorithms and hardness of approximation',category_assignment=dict(method='editorial_topic',reason='Offline approximation of a scheduling objective with machine-specific norms; no online arrival model is present.'),formal='Does generalized makespan on unrelated machines admit a polynomial-time O(√log n)-approximation, where n is the number of jobs? The target is to assign every job to one machine so that the maximum machine norm-load is at most C√log n times optimum, for a universal constant C and n≥2. The norm-access and algorithmic cost conventions remain a specification dependency.',definitions='There are n jobs and m machines, with nonnegative processing times pᵢⱼ that may depend arbitrarily on both the machine i and job j. Each machine has its own symmetric monotone norm ψᵢ on ℝⁿ. A norm is positive except at zero, satisfies ψᵢ(αu)=|α|ψᵢ(u) and ψᵢ(u+v)≤ψᵢ(u)+ψᵢ(v); it is symmetric if permuting coordinates preserves its value and monotone if 0≤u≤v coordinatewise implies ψᵢ(u)≤ψᵢ(v). An assignment ρ:{1,…,n}→{1,…,m} gives machine i the vector uᵢ with uᵢ(j)=pᵢⱼ when ρ(j)=i and zero otherwise. Its load is ψᵢ(uᵢ). Define M(ρ)=maxᵢ ψᵢ(uᵢ) and OPT=minρ M(ρ). The approximation factor must be uniform over all machines, processing times and allowed norms, with no factor depending on m. All jobs and machines are given together: this is an offline problem. It is not ordinary makespan unless every ψᵢ is the sum norm, and the outer objective is always the maximum, not an arbitrary norm of the machine-load vector.',question_type='yes_no',answer_criterion='After fixing the norm-access, arithmetic and randomized-guarantee conventions, obtain a polynomial-time assignment algorithm with ratio O(√log n), or rule out that ratio in the same model. An algorithm only for top-k or sum norms does not cover the general target. The conjecture’s suggested technique is omitted; its substantive approximation guarantee is retained.',context_blocks=[b('Each machine can measure its load differently','The input specifies how the vector of job sizes contributes to each machine’s load. The optimizer must keep the largest of these loads small, so replacing a norm by ordinary total processing time changes the problem.'),b('The known general upper bound is logarithmic','Deng, Li and Rabani give an O(log n) approximation even for a general outer norm. Their guarantee applies to the maximum outer norm required here.', 'gmp_upper'),b('The LP gap is a different kind of lower bound','The source exhibits a configuration-relaxation integrality gap Ω(√log n), already for a shared inner norm. This compares integral assignments to a fractional optimum; it is not a hardness theorem against every algorithm.', 'primary'),b('Constant approximation is conditionally ruled out','The source proves Ω((log n)^δ) approximation hardness for some fixed δ>0 under NP⊄ZTIME(n^{O(log log n)}), where ZTIME denotes zero-error randomized time. This does not establish a matching √log n hardness bound.', 'primary'),b('The remaining algorithmic convention',issue)],why='Would narrow the gap between the known logarithmic approximation and lower bounds for scheduling with general machine-specific measures of load.',references=refs,progress=[dict(date='2023',text='A logarithmic approximation is available for the more general load-balancing problem.',citation='gmp_upper'),dict(date='2023',text='The source proves a square-root-logarithmic configuration-LP gap and polylogarithmic approximation hardness, then conjectures the square-root-logarithmic algorithmic guarantee.',citation='primary')],status='source_open',status_note='The full conjecture, both definitions of generalized load balancing, the known upper bound and the original arXiv record were checked; no later resolution was located through 12 September 2026. Norm-access and runtime conventions remain explicit dependencies.',model_self_contained=False,requires_context=True,statement_review=unfinished(issue),importance=imp(c,'A sharp approximation question for scheduling under arbitrary symmetric monotone machine loads.'),review_note='Restored √log n, defined machine-specific inner norms and the maximum outer objective, removed rounding advice, corrected the online-algorithms classification and separated LP gaps from computational hardness.',working_summary=sm(['Assign all jobs to unrelated machines while minimizing the maximum machine load.','A machine’s load is a symmetric monotone norm of its assigned processing times, and norms may differ between machines.','The conjectured ratio is O(√log n), improving on the known O(log n) guarantee.','A matching-order fractional-relaxation gap is known, but it is not a matching hardness result for arbitrary algorithms.','The exact norm-access and runtime conventions still need to be stated.'],['primary','gmp_upper'])),notes=['Restored the radical, job parameter, assignment objective and arbitrary machine-specific norms.','Removed method advice and corrected the offline approximation category.','Separated computational hardness from integrality gaps and exposed the missing norm-access/cost convention.'],checked_sources=[r['url'] for r in refs]+['https://arxiv.org/abs/2202.06292','https://arxiv.org/abs/2307.13937'],state='improved_unfinished')
